#!/usr/bin/env bash
# Capture (or verify) the ribbon_waves fixture corpus.
#
# The corpus is captured from the peggle_evolved dev tree, not from the pinned
# M1 reference: src/levels/ribbon_waves.lua is untracked there (generated by
# julia_clone/tools/generate_ribbon_waves_level.py from the smoothed geometry)
# and the dev config is the same overlay the mustache corpus uses. Outputs:
#
#   fixtures/ribbon_waves/source/ribbon_waves_geometry.json  upstream geometry copy
#   fixtures/ribbon_waves/artifact/ribbon_waves.v1.json      level artifact (real provenance)
#   fixtures/ribbon_waves/config.dev.v1.json                 dev config artifact
#   fixtures/ribbon_waves/expected/*.json                    fixture records
#   fixtures/ribbon_waves/traces/*.jsonl                     snapshot-free gameplay traces
#   fixtures/ribbon_waves/mask_diff.png                      cleaned-mask diff (capture only)
#   fixtures/ribbon_waves/mask_diff_raw.png                  raw-mask diff (capture only)
#   fixtures/ribbon_waves/mask_metrics.json                  mask metrics (capture only)
#
# The corpus is deliberately outside the M1 fixture corpus; `make check-all`
# never re-captures it. See fixtures/ribbon_waves/README.md.
#
# The mask checker validates the **exported artifact** silhouette (world pegs
# inverted back to native space) against the cleaned reference mask. The raw
# mask has speckles and brick seams; cleaning closes each ribbon band with a
# 5 px disk and fills its holes, leaving the 53 circles untouched. The gate is
# cleaned IoU >= 0.92 overall and >= 0.86 per ribbon band (0.97/0.95 is the
# fidelity reference, not a gate).
#
# Usage (from anywhere; paths resolve relative to this script):
#   scripts/capture_ribbon_waves.sh          # re-export and capture the corpus
#   scripts/capture_ribbon_waves.sh --check  # verify only; never writes the corpus
#
# Check mode re-exports the artifacts to a temporary directory, requires them
# to be byte-identical to the committed ones (and the source geometry copy to
# match the upstream extraction), runs the mask checker with temporary
# diff/metrics outputs, and runs the harness fixture mode with --check
# (records and traces are re-captured in memory/temp files).
#
# Requires LuaJIT, LÖVE (scripts/love.sh handles headless displays), Python 3,
# the upstream extraction under ../level_segment/, and the generated
# ../peggle_evolved/src/levels/ribbon_waves.lua.
set -euo pipefail

repo_root="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
cd "$repo_root"

check=0
for arg in "$@"; do
  case "$arg" in
    --check) check=1 ;;
    *)
      echo "ERROR: unknown argument: $arg (only --check is supported)" >&2
      exit 2
      ;;
  esac
done

ref_dir="$repo_root/../peggle_evolved"
level_source="$ref_dir/src/levels/ribbon_waves.lua"
config_source="$ref_dir/src/config.lua"
upstream_geometry="$repo_root/../level_segment/ribbon_waves_geometry.json"
fixture_dir="$repo_root/fixtures/ribbon_waves"
source_geometry="$fixture_dir/source/ribbon_waves_geometry.json"
mask="$fixture_dir/reference/peg_mask.png"
mask_checker="$repo_root/scripts/check_ribbon_waves_mask.py"

if [[ ! -d "$ref_dir" ]]; then
  echo "ERROR: dev tree not found at $ref_dir" >&2
  exit 1
fi
if [[ ! -f "$level_source" ]]; then
  echo "ERROR: ribbon_waves level source not found at $level_source" >&2
  echo "       run julia_clone/tools/generate_ribbon_waves_level.py first" >&2
  exit 1
fi
if [[ ! -f "$config_source" ]]; then
  echo "ERROR: dev config not found at $config_source" >&2
  exit 1
fi
if [[ ! -f "$upstream_geometry" ]]; then
  echo "ERROR: geometry not found at $upstream_geometry" >&2
  exit 1
fi
if [[ ! -f "$mask" ]]; then
  echo "ERROR: reference mask not found at $mask" >&2
  exit 1
fi
if [[ ! -f "$mask_checker" ]]; then
  echo "ERROR: mask checker not found at $mask_checker" >&2
  exit 1
fi

# The source geometry copy is the transform the mask checker and the level
# generator share. It must match the upstream extraction byte-for-byte.
if [[ $check -eq 1 ]]; then
  if [[ ! -f "$source_geometry" ]]; then
    echo "ERROR: source geometry copy missing at $source_geometry" >&2
    exit 1
  fi
  if ! cmp -s "$upstream_geometry" "$source_geometry"; then
    echo "ERROR: $source_geometry differs from $upstream_geometry" >&2
    echo "       re-run without --check to refresh the fixture copy" >&2
    exit 1
  fi
else
  mkdir -p "$fixture_dir/source"
  cp "$upstream_geometry" "$source_geometry"
fi

# Validate fitted arcs: outward steepening, correct bend, tangent joins.
python3 "$repo_root/tools/generate_ribbon_waves_level.py" \
  --geometry "$upstream_geometry" --check-geometry

if ! revision="$(git -C "$ref_dir" rev-parse HEAD 2>/dev/null)"; then
  echo "ERROR: cannot read HEAD from $ref_dir (not a git checkout?)" >&2
  exit 1
fi
if ! tree="$(git -C "$ref_dir" rev-parse 'HEAD^{tree}' 2>/dev/null)"; then
  echo "ERROR: cannot read tree hash from $ref_dir" >&2
  exit 1
fi
config_sha="$(sha256sum "$config_source" | awk '{print $1}')"

echo "capture_ribbon_waves: dev tree $ref_dir"
echo "  revision   = $revision"
echo "  tree       = $tree"
echo "  config_sha = $config_sha"
echo "  geometry   = $(sha256sum "$source_geometry" | awk '{print $1}')"

artifact="$fixture_dir/artifact/ribbon_waves.v1.json"
config_artifact="$fixture_dir/config.dev.v1.json"

tmpdir=""
if [[ $check -eq 1 ]]; then
  tmpdir="$(mktemp -d "${TMPDIR:-/tmp}/capture_ribbon_waves.XXXXXX")"
  trap 'rm -rf "$tmpdir"' EXIT
  artifact_out="$tmpdir/ribbon_waves.v1.json"
  config_out="$tmpdir/config.dev.v1.json"
  diff_out="$tmpdir/mask_diff.png"
  diff_raw_out="$tmpdir/mask_diff_raw.png"
  metrics_out="$tmpdir/mask_metrics.json"
else
  mkdir -p "$fixture_dir/artifact" "$fixture_dir/expected" "$fixture_dir/traces"
  artifact_out="$artifact"
  config_out="$config_artifact"
  diff_out="$fixture_dir/mask_diff.png"
  diff_raw_out="$fixture_dir/mask_diff_raw.png"
  metrics_out="$fixture_dir/mask_metrics.json"
fi

luajit "$repo_root/tools/export_level.lua" \
  --reference "$ref_dir" \
  --level ribbon_waves \
  --out "$artifact_out" \
  --check \
  --revision "$revision" \
  --tree "$tree" \
  --config-sha256 "$config_sha"

luajit "$repo_root/tools/export_config.lua" \
  --reference "$ref_dir" \
  --out "$config_out" \
  --check \
  --source-sha256 "$config_sha"

if [[ $check -eq 1 ]]; then
  if ! cmp -s "$artifact_out" "$artifact"; then
    echo "ERROR: re-exported level artifact differs from $artifact" >&2
    exit 1
  fi
  if ! cmp -s "$config_out" "$config_artifact"; then
    echo "ERROR: re-exported config artifact differs from $config_artifact" >&2
    exit 1
  fi
  echo "artifacts: re-exports match the committed bytes"
fi

# Rasterize the exported artifact (in native space via the geometry's world
# block) and compare it with the cleaned reference mask.
python3 "$mask_checker" \
  --artifact "$artifact_out" \
  --mask "$mask" \
  --source-geometry "$source_geometry" \
  --diff "$diff_out" \
  --diff-raw "$diff_raw_out" \
  --metrics "$metrics_out"

args=(
  --fixtures
  --catalog "$fixture_dir/catalog.lua"
  --fixtures-out "$fixture_dir/expected"
  --fixtures-traces "$fixture_dir/traces"
  --reference-dir "$ref_dir"
  --artifact-dir "$fixture_dir/artifact"
  --reference-revision "$revision"
  --reference-tree "$tree"
  --config-sha256 "$config_sha"
)
if [[ $check -eq 1 ]]; then
  args+=(--check)
fi

"$repo_root/scripts/love.sh" love "$repo_root/harness" -- "${args[@]}"
